program = '''import math

def line(a, b):
    r0,c0=a; r1,c1=b
    dr=r1-r0; dc=c1-c0
    if dr and dc and abs(dr)!=abs(dc):
        return None
    n=max(abs(dr),abs(dc))
    if n==0: return [a]
    sr=(dr>0)-(dr<0); sc=(dc>0)-(dc<0)
    return [(r0+i*sr,c0+i*sc) for i in range(n+1)]

def cyclic(points):
    r=sum(p[0] for p in points)/len(points)
    c=sum(p[1] for p in points)/len(points)
    return sorted(points,key=lambda p:math.atan2(p[0]-r,p[1]-c))

def make_path(points):
    if len(points)<2: return None
    pts=cyclic(points)
    cells=[]
    for i,a in enumerate(pts):
        seg=line(a,pts[(i+1)%len(pts)])
        if seg is None: return None
        cells.extend(seg)
    return set(cells)

def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    positions={color:[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color] for color in range(1,10)}
    paths={}
    for color in (1,2,3,4,6,7,8):
        p=positions[color]
        valid=(color in (2,4) and len(p)>=2) or (color not in (2,4) and len(p)>=3)
        if valid:
            path=make_path(p)
            if path is not None: paths[color]=path
    # Two magenta points define a symmetric V.
    if len(positions[6])==2:
        a,b=positions[6]
        if abs(a[0]-b[0])==abs(a[1]-b[1]):
            bm=(b[0],2*a[1]-b[1])
            p1=line(a,b); p2=line(a,bm)
            if p1 and p2: paths[6]=set(p1+p2)
    partners={4:(6,2),7:(6,),1:(8,),8:(1,)}
    for secondary,primaries in partners.items():
        if len(positions[secondary])!=1: continue
        s=positions[secondary][0]
        candidates=[]
        for primary in primaries:
            if primary not in paths: continue
            for p in paths[primary]:
                dr=s[0]-p[0]; dc=s[1]-p[1]
                translated={(r+dr,c+dc) for r,c in paths[primary]}
                if all(0<=r<h and 0<=c<w for r,c in translated):
                    candidates.append((primary,translated))
        if candidates:
            primary,translated=min(candidates,key=lambda x:sum((r-s[0])**2+(c-s[1])**2 for r,c in x[1]))
            for r,c in translated: out[r][c]=secondary
    for color,path in paths.items():
        for r,c in path:
            if 0<=r<h and 0<=c<w: out[r][c]=color
    return out
'''
